function computeLeitnerSchedule(currentBox, rating) {
  let newBox = 1;
  let intervalMs = 4 * 60 * 60 * 1e3;
  if (rating === "easy") {
    newBox = Math.min(5, Math.max(1, currentBox) + 1);
    switch (newBox) {
      case 2:
        intervalMs = 24 * 60 * 60 * 1e3;
        break;
      case 3:
        intervalMs = 3 * 24 * 60 * 60 * 1e3;
        break;
      case 4:
        intervalMs = 7 * 24 * 60 * 60 * 1e3;
        break;
      case 5:
        intervalMs = 14 * 24 * 60 * 60 * 1e3;
        break;
      default:
        intervalMs = 24 * 60 * 60 * 1e3;
    }
  } else {
    newBox = 1;
    intervalMs = 4 * 60 * 60 * 1e3;
  }
  const now = Date.now();
  return {
    newBox,
    intervalMs,
    nextReviewAt: new Date(now + intervalMs).toISOString(),
    reviewedAt: new Date(now).toISOString()
  };
}
