router3.get("/api/admin/users", verifyAdminAuth, async (req, res) => {
  try {
    const page = Math.max(1, parseInt(req.query.page, 10) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit, 10) || 50));
    const search = (req.query.search || "").toLowerCase().trim();
    const role = (req.query.role || "").toUpperCase().trim();
    const status = (req.query.status || "").toUpperCase().trim();
    if (pgPool) {
      try {
        const offset = (page - 1) * limit;
        const whereClauses = [];
        const params = [];
        let paramIdx = 1;
        if (search) {
          whereClauses.push(`(email ILIKE $${paramIdx} OR COALESCE(data->>'name', '') ILIKE $${paramIdx})`);
          params.push(`%${search}%`);
          paramIdx++;
        }
        if (role && role !== "ALL") {
          whereClauses.push(`(data->>'role' = $${paramIdx})`);
          params.push(role);
          paramIdx++;
        }
        if (status && status !== "ALL") {
          whereClauses.push(`(data->>'status' = $${paramIdx})`);
          params.push(status);
          paramIdx++;
        }
        const whereSql = whereClauses.length > 0 ? `WHERE ${whereClauses.join(" AND ")}` : "";
        const countRes = await queryPostgres(
          `SELECT COUNT(*) as total FROM public.admin_users ${whereSql};`,
          params
        );
        const total2 = parseInt(countRes.rows[0]?.total || "0", 10);
        const usersRes = await queryPostgres(
          `SELECT id, user_id, email, data, created_at, updated_at
           FROM public.admin_users
           ${whereSql}
           ORDER BY updated_at DESC
           LIMIT $${paramIdx} OFFSET $${paramIdx + 1};`,
          [...params, limit, offset]
        );
        const mappedUsers = usersRes.rows.map((row) => {
          const d = row.data || {};
          return {
            id: row.id,
            name: d.name || row.email?.split("@")[0] || "Aspirant",
            email: row.email,
            role: d.role || "USER",
            isPremium: Boolean(d.isPremium),
            planName: d.planName || (d.isPremium ? "PRO PASS" : "FREE"),
            streakDays: Number(d.streakDays ?? 1),
            xp: Number(d.xp ?? 100),
            coins: Number(d.coins ?? 50),
            level: Number(d.level ?? 1),
            stateName: d.stateName || "All India",
            exam: d.exam || "NEET_UG",
            completedTopicsCount: Number(d.completedTopicsCount || 0),
            joinedAt: d.joinedAt || row.created_at || (/* @__PURE__ */ new Date()).toISOString(),
            status: d.status || "ACTIVE",
            avatar_url: d.avatar_url || ""
          };
        });
        const totalPages2 = Math.ceil(total2 / limit) || 1;
        return res.json({
          success: true,
          users: mappedUsers,
          total: total2,
          page,
          totalPages: totalPages2
        });
      } catch (dbErr) {
        console.warn("[Admin Users] Neon query error:", dbErr?.message || dbErr);
      }
    }
    let allUsers = [...adminUsersDb];
    if (search) {
      allUsers = allUsers.filter(
        (u) => u.name && u.name.toLowerCase().includes(search) || u.email && u.email.toLowerCase().includes(search)
      );
    }
    if (role && role !== "ALL") {
      allUsers = allUsers.filter((u) => u.role === role);
    }
    if (status && status !== "ALL") {
      allUsers = allUsers.filter((u) => u.status === status);
    }
    const total = allUsers.length;
    const totalPages = Math.ceil(total / limit) || 1;
    const startIndex = (page - 1) * limit;
    const paginatedUsers = allUsers.slice(startIndex, startIndex + limit);
    res.json({
      success: true,
      users: paginatedUsers,
      total,
      page,
      totalPages
    });
  } catch (err) {
    res.json({ success: true, users: adminUsersDb.slice(0, 50), total: adminUsersDb.length, page: 1, totalPages: 1 });
  }
});
