    const rawPayload = req.rawBody || JSON.stringify(req.body);
    const expectedSignature = crypto5.createHmac("sha256", webhookSecret).update(rawPayload).digest("hex");
    const bufExpected = Buffer.from(expectedSignature, "utf-8");
    const bufReceived = Buffer.from(webhookSignature, "utf-8");
    if (bufExpected.length !== bufReceived.length || !crypto5.timingSafeEqual(bufExpected, bufReceived)) {
      console.error("SECURITY ALERT: Invalid Razorpay webhook signature");
      return res.status(400).json({ error: "Invalid webhook signature" });
    }
